INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1475421-mis302', 'stk-ksa-wolf', 'MIS 302', 'info', '{"desc": "MIS 302 Business Applications Development\nالمادة مادة إلكتف لطلاب ال MIS\n* جودة المقرر بشكل عام:\nالمادة في نظري مهمة للي يبغى يطبق أو يتوظف في مجال تكنيكال… و لها وزن قوي في ال CV\n\n* المواضيع التي يغطيها المقرر :\nال 302، راح تتعلم فيها ٍالبرنامج Visual Studio which is a framework program\nframework program يعني أنه يجمع أكثر من لغة في برنامج واحد، يعني يصير ال Runtime, Libraries كلها في إديتور واحد. ال Visual Studio يدعم أربع لغات برمجة VB , C#, C++ , and F# these are the languages.\nأنت راح تدرس ال VB بشكل موسع (و هي لغة برمجة خاصة بفيجوال أستوديو) و التي تستطيع من خلالها عمل تطبيقات داخل الويندوز (ًWindows based applications) مثل الحاسبة في جهازك.\n\nثم بعدها ستدرس أداة ألا و هي ال ASP.NET، هذه الأداة تمكنك من عمل Web applications (Web forms) مثل المواقع أونلاين و امتدادها .aspx مثل موقع الجامعة http://www.kfupm.edu.sa/default.aspx ميزة هذه الأداة أنها تمكنك من العمل على أي لغة تريدها من اللغات السابقة: و اللغة المستخدمة مع هذه الأداة تسمى باسمها و زيادة عليها .NET\nExamples: VB.NET , C#.NET , C++.NET , F#.NET\n\n* الكتاب المستخدم للمقرر:\nالكتاب أنا أشوفه جدا مناسب و ممتاز، و يفهم المادة بشكل قوي. و فيه تمارين كثير مفيدة.\n\n* الأسئلة والأمثلة المستخدمة في المقرر:\nمثل ما قلت سابقا الكتاب جدا رائع. و إذا أنت متابع مع الدكتور السلايدات تكفيك عن الكتاب.\n\n* مدى فائدته في الناحية التطبيقية:\nمفيد جدا.\nالمادة هي تكملة لل MIS 301 , MIS 311: يعني بالمفهوم البسيط لو تبغى تبني سستم بتمر بثلاث مراحل:\nأولا: ال 301 هي ال التخطيط و الجانب النظري لبناء سستم، نشبهها بال(Blueprint).\n\nثانيا: تحتاج مكان تخزن فيه المعلومات، و نظام التخزين القديم مثل الأكسس و الورق ما يصلح في الوقت الحالي… فتحتاج تتعلم ال Relational Database فتدرس ال 311 و تتعلم كيف تبني الداتابيس بالشكل الصحيح و تبعد عن الأخطاء في بنائها.\n\nثالثا: 302 هنا أعتبرها ال interface للسستم، فهي تربط ال 301 و 311 مع بعض بإنتر فيس.\nفهنا تجي أهمية المادة (لو تبغى تشتغل في مجال تكنيكال)، لو سألوك الشركة تسوي سستم و جبت لهم السستم في ورق بشغل ال 301 و 311 ما راح يقبلوه، أيضا لو سويتها ببرامج المحاكاة (مثل: POPAPP , JustInMind) أيضا ما بيقبلوه، و بيقولون لك حنا نبغى سستم حي، سستم شغال قدامنا نقدر نستخدمه.\n\nملاحظة/ يفضل و بقوة يكون عندك خبرة في اللغات HTML, CSS , JavaScript قبل البدء في هذه المادة أو على الأقل قبل البدء في جزء ال ASP.NET\nهذا المقطع على اليوتيوب جدا ممتاز، مدته 5 ساعات تقريبا و سيعلمك أساسيات اللغتين HTML, CSS من إلى… و الرجال اللي يشرح إنسان خفيف دم و فله فما راح تطفش معه:\n\nhttps://www.youtube.com/watch?v=y3UH2gAhwPI\n\nبالنسبة للجافا سكربت أنا خلصت الكورس و ما أعرف عنها شي… يفضل تدرسها قبل، لأن فيه أشياء كثيييير في البروجكت حليناها بحلول معقدة و طويلة و كان بإمكاننا حلها في سطرين بالجافا سكربت.\n\nفي النهاية لا تلخبط الجافا بالجافا سكربت (Java Vs. JavaScript)… لغتين مختلفة اخلافا تاما عن بعض… و الجافا سكربت أسهل بكثير من الجافا ، فقط تم تسميتها جافا سكربت لأغراض تجارية و تسويقية.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mis-302-business-applications-development/120975/2", "user": "KSA-WOLF", "ts": 1497784928000, "tid": 120975, "pn": 2}}', 1497784928000, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
